// ApplicationsServiceServer is the server API for ApplicationsService service.
// All implementations must embed UnimplementedApplicationsServiceServer
// for forward compatibility.
//
// =============================================================================
// ApplicationsService
//
// Handles CRUD for agents, pipelines, and skills; versioning; publish /
// unpublish lifecycle; export / import; icon management; recommendations;
// pipeline triggers; forking; and draft generation.
// =============================================================================
type ApplicationsServiceServer interface {
	// ListApplications returns a paginated list of applications for a project.
	// Covers: applicationList (general browse) and totalApplications (count-only
	// probe with limit=1, offset=0) — same URL, query-param-driven.
	ListApplications(context.Context, *ListApplicationsRequest) (*PaginatedApplicationsResponse, error)
	// ListPublicApplications returns published applications visible without
	// project membership.
	// Covers: publicApplicationsList, totalPublicApplications,
	//
	//	totalMyLikedPublicApplications, totalTrendingPublicApplications.
	//
	// The trailing-slash variant is registered as an additional binding for
	// backward compatibility.
	ListPublicApplications(context.Context, *ListPublicApplicationsRequest) (*PaginatedApplicationsResponse, error)
	// CreateApplication creates a new application (agent / pipeline / skill) shell.
	CreateApplication(context.Context, *CreateApplicationRequest) (*CreateApplicationResponse, error)
	// EditApplication updates top-level application metadata in-place.
	EditApplication(context.Context, *EditApplicationRequest) (*GenericResponse, error)
	// GetApplication retrieves full application details.
	// Covers: applicationDetails, forkedFromApplicationDetails, and
	// applicationSelectItemDetails — all three hit the same URL.
	GetApplication(context.Context, *GetApplicationRequest) (*GetApplicationResponse, error)
	// DeleteApplication removes an application and all associated versions.
	DeleteApplication(context.Context, *DeleteApplicationRequest) (*GenericResponse, error)
	// DeleteApplicationTool removes a tool (skill entity).
	DeleteApplicationTool(context.Context, *DeleteApplicationToolRequest) (*GenericResponse, error)
	// GetPublicApplication retrieves a published application by its public name
	// and version label.
	GetPublicApplication(context.Context, *GetPublicApplicationRequest) (*GetPublicApplicationResponse, error)
	// PublishApplication transitions a version to the published (marketplace) state.
	PublishApplication(context.Context, *PublishApplicationRequest) (*GenericResponse, error)
	// UnpublishApplication retracts a published version from the marketplace.
	UnpublishApplication(context.Context, *UnpublishApplicationRequest) (*GenericResponse, error)
	// ValidateForPublish runs pre-publish validation checks without committing.
	ValidateForPublish(context.Context, *ValidateForPublishRequest) (*GenericResponse, error)
	// StopApplicationTask cancels a running asynchronous application task.
	StopApplicationTask(context.Context, *StopApplicationTaskRequest) (*GenericResponse, error)
	// GetApplicationVersionDetail retrieves a specific application version.
	GetApplicationVersionDetail(context.Context, *GetApplicationVersionDetailRequest) (*GenericResponse, error)
	// SaveApplicationNewVersion creates a new version for an existing application.
	SaveApplicationNewVersion(context.Context, *SaveApplicationNewVersionRequest) (*GenericResponse, error)
	// UpdateApplicationVersion updates mutable fields of a specific version.
	UpdateApplicationVersion(context.Context, *UpdateApplicationVersionRequest) (*GenericResponse, error)
	// SetApplicationDefaultVersion marks a version as the default for its parent
	// application.  The version_id is supplied in the request body.
	SetApplicationDefaultVersion(context.Context, *SetApplicationDefaultVersionRequest) (*GenericResponse, error)
	// DeleteApplicationVersion removes a version.  The optional
	// replacement_version_id query parameter causes existing references to be
	// repointed before deletion.
	DeleteApplicationVersion(context.Context, *DeleteApplicationVersionRequest) (*GenericResponse, error)
	// CheckVersionInUse reports whether a version is referenced by other entities
	// (e.g. toolkits, other application versions).
	CheckVersionInUse(context.Context, *CheckVersionInUseRequest) (*GenericResponse, error)
	// BatchReplaceVersionReferences atomically repoints all references from
	// old_version_id to new_version_id.  The delete_old query parameter removes
	// the old version after replacement.
	BatchReplaceVersionReferences(context.Context, *BatchReplaceVersionReferencesRequest) (*GenericResponse, error)
	// ValidateApplicationVersion validates a version's configuration against
	// current platform constraints.
	ValidateApplicationVersion(context.Context, *ValidateApplicationVersionRequest) (*GenericResponse, error)
	// ExportApplication exports an application as JSON or Markdown.
	// Covers: applicationExport (format=json, default) and applicationExportMd
	// (format=md).  Both callers hit the same URL; the format query parameter
	// selects the response shape.  When format=md, the response contains a
	// BlobResult; otherwise a json_data Struct is returned.
	ExportApplication(context.Context, *ExportApplicationRequest) (*ExportApplicationResponse, error)
	// ConvertLegacyApplication converts a legacy-format application payload into
	// the current schema.
	ConvertLegacyApplication(context.Context, *ConvertLegacyApplicationRequest) (*GenericResponse, error)
	// ImportWizard runs the guided multi-step import flow for an application
	// payload into a target project.
	ImportWizard(context.Context, *ImportWizardRequest) (*GenericResponse, error)
	// UploadApplicationIcon uploads a new icon for a specific application version.
	// The legacy endpoint uses multipart/form-data.  The chi handler in
	// elitea-main decodes the multipart body and populates this message; the
	// grpc-gateway HTTP rule maps the non-path fields from the JSON body as a
	// fallback for API clients that send JSON.
	UploadApplicationIcon(context.Context, *UploadApplicationIconRequest) (*GenericResponse, error)
	// ReplaceApplicationIcon replaces an existing icon's metadata / file for a
	// version.
	ReplaceApplicationIcon(context.Context, *ReplaceApplicationIconRequest) (*GenericResponse, error)
	// DeleteApplicationIcon removes an icon by its storage name/key.
	DeleteApplicationIcon(context.Context, *DeleteApplicationIconRequest) (*GenericResponse, error)
	// GetApplicationIcons lists uploaded icons for a project with pagination.
	// Note: this endpoint uses "skip" (not "offset") as the pagination cursor.
	GetApplicationIcons(context.Context, *GetApplicationIconsRequest) (*GetApplicationIconsResponse, error)
	// GetApplicationDefaultIcons returns the platform-level default icon set.
	GetApplicationDefaultIcons(context.Context, *GetApplicationDefaultIconsRequest) (*GenericResponse, error)
	// UpdateApplicationRelation updates the typed relationship between two
	// application versions (e.g. parent-child, dependency).
	UpdateApplicationRelation(context.Context, *UpdateApplicationRelationRequest) (*GenericResponse, error)
	// SetAgentAttachmentStorage configures which toolkit handles file-attachment
	// storage for a specific agent version.
	SetAgentAttachmentStorage(context.Context, *SetAgentAttachmentStorageRequest) (*GenericResponse, error)
	// GetRecommendations returns applications recommended for a project based on
	// platform-wide usage trends within the given day window.
	GetRecommendations(context.Context, *GetRecommendationsRequest) (*ArrayResponse, error)
	// GetDocumentLoaders returns the available document loader / index type
	// configurations for a project (used when setting up datasource indexing).
	GetDocumentLoaders(context.Context, *GetDocumentLoadersRequest) (*ArrayResponse, error)
	// GetPipelineTrigger retrieves the scheduled/event trigger for a pipeline
	// version.
	GetPipelineTrigger(context.Context, *GetPipelineTriggerRequest) (*GenericResponse, error)
	// UpdatePipelineTrigger sets or replaces the trigger configuration.
	UpdatePipelineTrigger(context.Context, *UpdatePipelineTriggerRequest) (*GenericResponse, error)
	// GetTrendingAuthors returns the list of authors with trending published agents
	// for a project context.
	GetTrendingAuthors(context.Context, *GetTrendingAuthorsRequest) (*GetTrendingAuthorsResponse, error)
	// ForkAgent copies a published application into the caller's project,
	// creating a new independently editable application.
	ForkAgent(context.Context, *ForkAgentRequest) (*GenericResponse, error)
	// GetAgentCategories returns the taxonomy used to classify published agents
	// in the marketplace.
	GetAgentCategories(context.Context, *GetAgentCategoriesRequest) (*GetAgentCategoriesResponse, error)
	// GenerateAgentDraft invokes the AI-assisted agent scaffolding service,
	// returning a pre-populated draft agent configuration.
	GenerateAgentDraft(context.Context, *GenerateAgentDraftRequest) (*GenericResponse, error)
	mustEmbedUnimplementedApplicationsServiceServer()
}

